import java.util.*;

public class Hello {

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        String inputStr = in.nextLine().trim();
        assert inputStr.length() >= 1 && inputStr.length() <= 8 : "Invalid input length";
        if (inputStr.charAt(0) == '0') {
            System.out.println(inputStr.length() > 1 ? "0" : "1");
            return;
        }
        int startNumber = Integer.parseInt("1" + "0".repeat(inputStr.length() - 1));
        if (startNumber == 1) {
            startNumber = 0;
        } else if (startNumber == 10) {
            startNumber = 25;
        }
        int endNumber = Integer.parseInt("9".repeat(inputStr.length()));
        int countMatches = 0;
        for (int num = startNumber; num <= endNumber; num += 25) {
            if (matchesPattern(num, inputStr)) {
                countMatches++;
            }
        }
        System.out.println(countMatches);
    }

    private static boolean matchesPattern(int number, String pattern) {
        String numStr = String.valueOf(number);
        char lastXChar = '*';
        for (int i = 0; i < pattern.length(); i++) {
            char pChar = pattern.charAt(i);
            if (pChar == '_') continue;
            if (pChar == 'X') {
                if (lastXChar != '*' && lastXChar != numStr.charAt(i)) return false;
                lastXChar = numStr.charAt(i);
            } else if (pChar != numStr.charAt(i)) {
                return false;
            }
        }
        return true;
    }
}
